package pe.vichaval.gestionriego.agricultor.entity;import jakarta.persistence.*;import pe.vichaval.gestionriego.agricultor.dto.*;@Entity@Table(name="agricultores")public class Agricultor{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true,length=8)private String dni;@Column(nullable=false)private String nombres;@Column(nullable=false)private String apellidos;private String telefono;@Column(nullable=false)private String sector;@Column(nullable=false)private String estado="ACTIVO";protected Agricultor(){}public Agricultor(AgricultorForm f){set(f);}public void set(AgricultorForm f){dni=f.getDni();nombres=f.getNombres();apellidos=f.getApellidos();telefono=f.getTelefono();sector=f.getSector();estado=f.getEstado();}public Long getId(){return id;}public String getDni(){return dni;}public String getNombres(){return nombres;}public String getApellidos(){return apellidos;}public String getTelefono(){return telefono;}public String getSector(){return sector;}public String getEstado(){return estado;}}